// Original bounded CPU fluid solver: semi-Lagrangian advection and pressure projection.
// Reference equations/controls: WebGL-Fluid-Simulation and svelte-fluid (see research roadmap).
// Self-contained factory is reused by offline HTML exports; no framework/GPU requirement.
export function createInk(resolution=32){
 const n=Math.max(16,Math.min(48,Math.round(Number.isFinite(resolution)?resolution:32))),length=n*n,make=()=>new Float32Array(length);let u=make(),v=make(),red=make(),green=make(),blue=make();const tmp=make(),pressure=make(),div=make(),curl=make(),idx=(x,y)=>Math.max(0,Math.min(n-1,y))*n+Math.max(0,Math.min(n-1,x));
 const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),rgb=(value,fallback)=>{const h=/^#[a-f\d]{6}$/i.test(value||'')?value:fallback;return [1,3,5].map(i=>parseInt(h.slice(i,i+2),16))};
 function advect(field,dt){for(let y=0;y<n;y++)for(let x=0;x<n;x++){const i=y*n+x,px=clamp(x-dt*u[i]*n,0,n-1.001),py=clamp(y-dt*v[i]*n,0,n-1.001),x0=Math.floor(px),y0=Math.floor(py),a=px-x0,b=py-y0;tmp[i]=(field[idx(x0,y0)]*(1-a)+field[idx(x0+1,y0)]*a)*(1-b)+(field[idx(x0,y0+1)]*(1-a)+field[idx(x0+1,y0+1)]*a)*b}field.set(tmp)}
 function project(){pressure.fill(0);for(let y=1;y<n-1;y++)for(let x=1;x<n-1;x++){const i=y*n+x;div[i]=-(u[i+1]-u[i-1]+v[i+n]-v[i-n])/(2*n)}for(let k=0;k<16;k++)for(let y=1;y<n-1;y++)for(let x=1;x<n-1;x++){const i=y*n+x;pressure[i]=(div[i]+pressure[i-1]+pressure[i+1]+pressure[i-n]+pressure[i+n])/4}for(let y=1;y<n-1;y++)for(let x=1;x<n-1;x++){const i=y*n+x;u[i]=clamp(u[i]-(pressure[i+1]-pressure[i-1])*n/2,-2,2);v[i]=clamp(v[i]-(pressure[i+n]-pressure[i-n])*n/2,-2,2)}for(let i=0;i<n;i++){u[i]=v[i]=u[(n-1)*n+i]=v[(n-1)*n+i]=0;u[i*n]=v[i*n]=u[i*n+n-1]=v[i*n+n-1]=0}}
 function splat(x,y,dx=0,dy=0,color='#a9d86c',radius=.08){if(![x,y,dx,dy,radius].every(Number.isFinite))return;const c=rgb(color,'#a9d86c').map(v=>v/255),r=clamp(radius,.02,.2)*n;for(let j=0;j<n;j++)for(let k=0;k<n;k++){const i=j*n+k,f=Math.exp(-((k-clamp(x,0,1)*n)**2+(j-clamp(y,0,1)*n)**2)/(r*r));u[i]=clamp(u[i]+clamp(dx,-2,2)*f,-2,2);v[i]=clamp(v[i]+clamp(dy,-2,2)*f,-2,2);red[i]=Math.min(5,red[i]+c[0]*f*1.5);green[i]=Math.min(5,green[i]+c[1]*f*1.5);blue[i]=Math.min(5,blue[i]+c[2]*f*1.5)}}
 function step(time,{dissipation=.5,swirl=20}={}){const dt=clamp(Number.isFinite(time)?time:0,0,1/30),strength=clamp(Number.isFinite(swirl)?swirl:20,0,50)*.01;for(let y=1;y<n-1;y++)for(let x=1;x<n-1;x++){const i=y*n+x;curl[i]=(v[i+1]-v[i-1]-u[i+n]+u[i-n])*.5}for(let y=1;y<n-1;y++)for(let x=1;x<n-1;x++){const i=y*n+x,gx=Math.abs(curl[i+1])-Math.abs(curl[i-1]),gy=Math.abs(curl[i+n])-Math.abs(curl[i-n]),norm=Math.hypot(gx,gy)+1e-6;u[i]=clamp(u[i]+gy/norm*curl[i]*strength*dt,-2,2);v[i]=clamp(v[i]-gx/norm*curl[i]*strength*dt,-2,2)}project();advect(u,dt);advect(v,dt);project();for(const dye of [red,green,blue]){advect(dye,dt);const decay=Math.exp(-clamp(Number.isFinite(dissipation)?dissipation:.5,.05,3)*dt);for(let i=0;i<length;i++)dye[i]*=decay}}
 function pixels(background='#101b24'){const bg=rgb(background,'#101b24'),data=new Uint8ClampedArray(length*4);for(let i=0;i<length;i++){for(let c=0;c<3;c++){const dye=[red,green,blue][c][i],a=1-Math.exp(-dye);data[i*4+c]=Math.round(bg[c]*(1-a)+255*a)}data[i*4+3]=255}return data}
 function svg(background='#101b24'){const bg=rgb(background,'#101b24'),data=pixels(background);let rect='';for(let y=0;y<n;y++)for(let x=0;x<n;x++){const i=(y*n+x)*4;if(Math.abs(data[i]-bg[0])+Math.abs(data[i+1]-bg[1])+Math.abs(data[i+2]-bg[2])<2)continue;rect+=`<rect x="${x*960/n}" y="${y*540/n}" width="${960/n+.1}" height="${540/n+.1}" fill="rgb(${data[i]},${data[i+1]},${data[i+2]})"/>`}return `<svg xmlns="http://www.w3.org/2000/svg" width="960" height="540" viewBox="0 0 960 540"><defs><filter id="ink-soft"><feGaussianBlur stdDeviation="${960/n*.25}"/></filter></defs><rect width="960" height="540" fill="rgb(${bg.join(',')})"/><g filter="url(#ink-soft)">${rect}</g></svg>`}
 function snapshot(){return {n,fields:[u,v,red,green,blue].map(a=>Array.from(a,v=>Math.round(v*10000)/10000))}}
 function restore(s){if(s?.n!==n||!Array.isArray(s.fields)||s.fields.length!==5||!s.fields.every(a=>Array.isArray(a)&&a.length===length&&a.every(Number.isFinite)))return false;[u,v,red,green,blue].forEach((a,k)=>a.set(s.fields[k].map(v=>clamp(v,k<2?-2:0,k<2?2:5))));return true}
 function clear(){for(const a of [u,v,red,green,blue])a.fill(0)}
 return {n,splat,step,pixels,svg,snapshot,restore,clear}
}
export function inkHTML(settings,snapshot){const safe=JSON.stringify({settings,snapshot}).replace(/</g,'\\u003c');return `<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>RepoShelf fluid ink</title><style>body{margin:0;background:#101b24;color:white;font:16px system-ui}canvas{width:100%;aspect-ratio:16/9;display:block;touch-action:none}button,p{margin:16px;padding:12px}</style><canvas id="ink" width="960" height="540" aria-label="Interactive fluid ink canvas"></canvas><button id="play" aria-pressed="false">Play simulation</button><button id="splat">Add ink</button><p>Drag to paint. Fluid is a simulation; it does not promise a seamless loop.</p><script>
const createInk=${createInk.toString()},saved=${safe},s=saved.settings,engine=createInk(saved.snapshot.n);engine.restore(saved.snapshot);const canvas=document.getElementById('ink'),ctx=canvas.getContext('2d'),small=document.createElement('canvas');small.width=small.height=engine.n;const smallCtx=small.getContext('2d'),button=document.getElementById('play'),reduce=matchMedia('(prefers-reduced-motion: reduce)');let playing=false,frame=0,last=0,point=null;function paint(){smallCtx.putImageData(new ImageData(engine.pixels(s.background),engine.n,engine.n),0,0);ctx.drawImage(small,0,0,960,540)}function tick(now){frame=0;if(!playing||document.hidden)return;const dt=Math.min(.1,last?(now-last)/1000:1/60)*s.speed,steps=Math.ceil(dt*30);for(let i=0;i<steps;i++)engine.step(dt/steps,s);last=now;paint();frame=requestAnimationFrame(tick)}function sync(){cancelAnimationFrame(frame);last=0;if(reduce.matches)playing=false;button.disabled=reduce.matches;button.textContent=reduce.matches?'Reduced motion enabled':playing?'Pause simulation':'Play simulation';button.setAttribute('aria-pressed',String(playing));if(playing&&!document.hidden)frame=requestAnimationFrame(tick)}function at(e){const r=canvas.getBoundingClientRect();return [(e.clientX-r.left)/r.width,(e.clientY-r.top)/r.height]}canvas.onpointerdown=e=>{point=at(e);canvas.setPointerCapture(e.pointerId);engine.splat(...point,0,0,s.ink,s.radius);paint()};canvas.onpointermove=e=>{if(!point)return;const p=at(e);engine.splat(p[0],p[1],(p[0]-point[0])*s.force,(p[1]-point[1])*s.force,s.ink,s.radius);point=p;paint()};canvas.onpointerup=canvas.onpointercancel=()=>point=null;document.getElementById('splat').onclick=()=>{engine.splat(.5,.5,.2,-.2,s.accent,s.radius);paint()};button.onclick=()=>{playing=!playing;sync()};reduce.addEventListener('change',sync);document.addEventListener('visibilitychange',sync);paint();sync();
</script></html>`}
